from pathlib import Path
import fitz
HERE=Path(__file__).resolve().parent
SRC=HERE/'frame-bearing-renewal-reassembly-v1.procedure.json'
OUT=HERE/'engine-removal-refit-v1.procedure.json'
if OUT.exists() and json.loads(OUT.read_text(encoding='utf8'))['source']['review_status']=='APPROVED':raise SystemExit('Frozen artifact; use a new revision.')
d=json.loads(SRC.read_text(encoding='utf8'));rows={s['id']:s for s in d['steps']}
ids=[s['id'] for s in d['steps'][:31]]+['engine-bench-record','engine-engine-in','engine-mount-torque','engine-release-refit','engine-pedal-refit','engine-sprocket-refit','engine-ground-starter','engine-harness-refit','engine-intake-refit','control-renew-lubricate','control-renew-ends-fit','control-renew-housing-close','control-renew-static-check','engine-hoses-refit','engine-exhaust-header-install','engine-exhaust-midpipe-install','engine-exhaust-silencer-install','engine-exhaust-joints-final','engine-access-case-refit','engine-access-intake-check','engine-access-tank-install','engine-cooling-fill','engine-cooling-cap','pressure-test','engine-oil-fill','engine-battery-refit','engine-access-body-install','engine-slack','engine-torque','engine-sprocket-final','engine-fuel-ready','engine-oil-flow','engine-cooling-warm-cool','control-renew-idle-check','control-renew-final-adjust','control-renew-steering-check','engine-complete-cooling','engine-cooling-recheck','engine-final-checks']
d['steps']=[copy.deepcopy(rows[x]) for x in ids]
d.update(id='yamaha-yz450f-2025-engine-removal-refit-v1',title='Remove the complete engine and refit it to the bike',completeness='Assembled exact stock bike to supported complete engine on a bench, then bike reassembly and operating checks. Wheels, fork, shock and linkage stay assembled. Internal engine work is a separate exact-year route with its own measured checks.')
d['applicability']['included']='Exact stock US 2025 YZ450F with serviceable frame, engine mounting interfaces, intact chain/sprockets and operating brakes. Cable clutch. No automatic year inheritance.'
d['applicability']['excluded']=['Other years/models or modified interfaces','Internal engine repairs unless separately source-reviewed and recorded','Wheel/frame/suspension bearing service or structural repair','Opening hydraulic brake circuits','Complete cable replacement or throttle-body sensor/calibration work','Broken chain, failed rear brake or seized sprocket nut preventing the reviewed manual holding method']
d['entry_state']=['Assembled exact stock bike; intact chain and working rear brake; original engine condition and routing recorded.']
d['exit_state']=['Engine refitted with mounting, electrical, intake, fuel, exhaust, cable clutch, chain, oil and cooling closure recorded; any separate internal job retains its own checks.']
d['affected_components']=['engine_modifications','chain','brakes','rear_brake','clutch','exhaust','intake']
d['editorial_template']={'path':SRC.name,'sha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'authority':'Same-year source-reviewed authoring companion; independent review pending. No frame-bearing steps implied.'}
d['required_parts']=[x for x in d['required_parts'] if any(w in x['name'].lower() for w in ['engine-oil','coolant','sprocket lock','exhaust','engine oil','harness ties','master-link','loctite','molybdenum','lithium','pedal pivot'])]
d['required_tools']=[{'name':x} for x in ['Stable motorcycle stand plus independent engine and swingarm supports, temporary pivot-support shaft and helper','Calibrated torque tools covering 1.5-90 Nm; correct sockets and manual breaker bar','Fuel-safe transfer equipment, containers, measured oil/coolant vessels and port covers','Configured Yamaha diagnostic tool 90890-03275 (US USB) or 90890-03273 and supplied instructions; digital tachometer 90890-06760/YU-39951-B','Radiator tester 90890-01325/YU-24460-A and adapter 90890-01352/YU-33984','Ruler/free-play gauge, means of applying approximately 50 N for chain slack; source-specific molybdenum-disulfide and lithium-soap greases']]
d['prerequisites']=['Match exact stock installed engine and cable-clutch interfaces; preserve original hose/cable routing photographs.','Independent engine, swingarm and chassis support required while the shared pivot is withdrawn. Wheels, suspension and brake hydraulic circuits remain assembled.','Serviceable intact stock chain, sprockets and working rear brake are required for the attributed manual sprocket-nut holding technique; no impact, heat or case jamming.','Internal bench work, if performed, must return a sealed engine with all plugs/covers/filter/O-rings correctly fitted and documented timing, clearance, lubrication and free-rotation checks before refit.','A separate head-gasket replacement requires the additional post-replacement cooling-system check stated in OEM PDF289 after 3 minutes warm-up. The cold retained-gasket pressure check here does not complete that separate requirement.']
d['supplemental_sources']=[x for x in d['supplemental_sources'] if 'Transmoto' in x['url']]
d['remaining_gaps']=['Internal engine operations and their measurements are separate records, not implied by engine installation.','The OEM head-gasket replacement pressure-test timing is an additional prerequisite of any separate gasket job.','Physical bike validation has not been performed.']
for s in d['steps']:
 if s['id']=='engine-bench-record':
  s['instruction']='Record the completed independent bench work, if any. Before refit confirm its timing, clearances, lubrication, free rotation and sealed cover/filter checks. This guide itself leaves engine internals intact. Keep the original swingarm and side stacks located on their temporary support and ready for the single pivot replacement.'
  s['verification']=['Bench condition and any separate internal repair record accepted; all covers/filter sealed; original swingarm side stacks retained and supported.']
 if s['id']=='engine-engine-in':s['instruction']='Bring the supported engine in from the right, lower part first, and align mounting points without trapping wires or hoses. Apply molybdenum-disulfide grease to the pivot and install from the right while withdrawing the temporary support shaft, keeping the original swingarm side stacks located. Apply lithium-soap grease to the pivot-nut threads and contact face.'
 if s['id']=='engine-sprocket-refit':s['instruction']=s['instruction'].replace('Fit the retained stock chain','With the supported rear wheel still installed, loosen the axle nut and both adjuster locknuts and back off adjusters enough to bring the wheel forward for chain installation. Fit the retained stock chain')
 if s['id']=='engine-access-case-release':s['instruction']=s['instruction'].replace('Do not move the cables.','Keep body-side cable ends undisturbed.')
 if s['id']=='engine-final-checks':s['instruction']+=' Verify wheels remain correctly secured, brakes firm, no trapped cable/hose, and all temporary supports and port covers removed. Record any fault before returning the bike to use.'
 if s['id']=='engine-initial-record':s['instruction']+=' Record initial clutch lever free play 7-12 mm and control condition before removing any cable end.'
 s['source_links']=[x for x in s['source_links'] if 'motionpro' not in (x if isinstance(x,str) else x['url'])]
for i,s in enumerate(d['steps']):s['depends_on']=[d['steps'][i-1]['id']] if i else []
p=fitz.open('C:/Users/kylej/AppData/Local/Temp/D02-2819U-10_02.pdf')
d['source']['pdf_pages']=sorted(set(x for s in d['steps'] for x in s['source_pdf_pages']))
d['source']['printed_pages']=list(dict.fromkeys(x for n in d['source']['pdf_pages'] for x in re.findall(r'^\d{1,2}-\d{1,3}$',p[n-1].get_text(),re.M)[-1:]))
d['source']['review_note']='Exact 2025 engine access, cable clutch, routing, mount preparation and fluid closure reviewed against D02. Same-year frame source steps composed with the wheels/suspension retained. Independent closure review pending.'
OUT.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
print(OUT.name,len(d['steps']),hashlib.sha256(OUT.read_bytes()).hexdigest())
